  const headScripts = "<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/katex@0.18.4/dist/katex.min.css" crossorigin="anonymous">
<script defer src="https://cdn.jsdelivr.net/npm/katex@0.18.4/dist/katex.min.js" crossorigin="anonymous"></script>
<script defer src="https://cdn.jsdelivr.net/npm/katex@0.18.4/dist/contrib/auto-render.min.js" crossorigin="anonymous"></script>
<script defer>
// Safe KaTeX helpers for BRIDGING — only typeset known question-prompt elements.

window.BRIDGING_MATH_ELEMENT_UIDS = [
  'ae5f2e79-0b46-4c4a-8e23-639000357860', // Topics question prompt
  'cb1a6e43-05fe-4831-8dc5-bed0b06045a5', // Practice question prompt
  'd1f67df6-fe79-4396-8be3-17d105df0a71', // Model answer
  '2b368312-9d8f-4345-af1f-f0ca9a0b5f94', // Worked solution
];

window.bridgingMathDelimiters = [
  { left: '$$', right: '$$', display: true },
  { left: '\\[', right: '\\]', display: true },
  { left: '\\(', right: '\\)', display: false },
];

var BRIDGING_UI_NOISE =
  /View all questions|Practice topic|Revision notes|Mastery score|Questions in this topic|Not started|attempted|mastery/i;

window.bridgingFixMojibake = function (text) {
  if (!text || typeof text !== 'string') return text;
  try {
    return decodeURIComponent(escape(text));
  } catch (e) {
    return text;
  }
};

window.bridgingNormalizeMath = function (text) {
  if (!text || typeof text !== 'string') return text;
  text = window.bridgingFixMojibake(text);
  text = text.replace(/\\\(([^\\]+?)\]\{([^}]+)\}\\\)/g, '\\($1^{$2}\\)');
  text = text.replace(/\^\{\(([^)]+)\)\}/g, '^{$1}');
  return text;
};

window.bridgingPreparePlainMath = function (text) {
  if (!text || typeof text !== 'string') return text;

  text = window.bridgingNormalizeMath(text);
  if (/\\\(|\\\[|\$\$/.test(text)) return text;

  return text.replace(
    /(\d+(?:\.\d+)?|[A-Za-z]+)\^([+-]?\d+(?:\.\d+)?|[A-Za-z]+)/g,
    function (_, base, exp) {
      return '\\(' + base + '^{' + exp + '}\\)';
    }
  );
};

window.bridgingNeedsMath = function (text) {
  if (!text) return false;
  return /\\\(|\\\[|\$\$|\^/.test(text);
};

window.bridgingIsPromptTextEl = function (el) {
  if (!el) return false;

  var tag = (el.tagName || '').toUpperCase();
  if (tag !== 'P' && tag !== 'SPAN') return false;
  if (el.querySelector('button, a, img, svg, input, textarea, div')) return false;
  if (el.children.length > 2) return false;

  var text = (el.textContent || '').trim();
  if (!text || text.length < 2 || text.length > 320) return false;
  if (BRIDGING_UI_NOISE.test(text)) return false;
  if (!window.bridgingNeedsMath(text)) return false;

  var host = el.closest('[data-ww-uid]');
  if (!host) return false;

  return window.BRIDGING_MATH_ELEMENT_UIDS.indexOf(host.getAttribute('data-ww-uid')) >= 0;
};

window.bridgingFindPromptTextNodes = function () {
  var nodes = [];
  var seen = new Set();

  (window.BRIDGING_MATH_ELEMENT_UIDS || []).forEach(function (uid) {
    document
      .querySelectorAll('[data-ww-uid="' + uid + '"] p, [data-ww-uid="' + uid + '"] span')
      .forEach(function (el) {
        if (seen.has(el)) return;
        if (!window.bridgingIsPromptTextEl(el)) return;
        seen.add(el);
        nodes.push(el);
      });
  });

  return nodes;
};

window.bridgingWaitForKaTeX = function (callback, triesLeft) {
  if (typeof renderMathInElement === 'function') {
    callback();
    return;
  }
  if (triesLeft === undefined) triesLeft = 120;
  if (triesLeft <= 0) return;
  setTimeout(function () {
    window.bridgingWaitForKaTeX(callback, triesLeft - 1);
  }, 50);
};

window.bridgingRenderMathInEl = function (el) {
  if (!el || typeof renderMathInElement !== 'function') return false;
  if (!window.bridgingIsPromptTextEl(el)) return false;
  if (el.querySelector('.katex')) return true;

  var raw = window.bridgingNormalizeMath((el.textContent || '').trim());
  if (!window.bridgingNeedsMath(raw)) return false;

  var prepared = window.bridgingPreparePlainMath(raw);
  var hash = prepared.length + '|' + prepared.slice(0, 120);

  if (el.getAttribute('data-katex-hash') === hash && el.querySelector('.katex')) {
    return true;
  }

  el.textContent = prepared;
  renderMathInElement(el, {
    delimiters: window.bridgingMathDelimiters,
    throwOnError: false,
  });

  el.setAttribute('data-katex-hash', hash);
  el.setAttribute('data-katex-rendered', 'true');
  return !!el.querySelector('.katex');
};

window.bridgingRenderMath = function () {
  window.bridgingWaitForKaTeX(function () {
    window.bridgingFindPromptTextNodes().forEach(function (el) {
      window.bridgingRenderMathInEl(el);
    });
  });
};

window.bridgingRenderMathBurst = function (durationMs, intervalMs) {
  var endAt = Date.now() + (durationMs || 4000);
  var interval = intervalMs || 300;

  var tick = function () {
    window.bridgingRenderMath();
    if (Date.now() < endAt) setTimeout(tick, interval);
  };

  tick();
};

window.bridgingAttachMathObservers = function () {
  if (!window.__bridgingMathHosts) window.__bridgingMathHosts = new WeakSet();
  if (!window.__bridgingMathObserver) return;

  (window.BRIDGING_MATH_ELEMENT_UIDS || []).forEach(function (uid) {
    document.querySelectorAll('[data-ww-uid="' + uid + '"]').forEach(function (host) {
      if (window.__bridgingMathHosts.has(host)) return;
      window.__bridgingMathHosts.add(host);
      window.__bridgingMathObserver.observe(host, {
        childList: true,
        subtree: true,
        characterData: true,
      });
    });
  });
};

window.bridgingEnsureMathObserver = function () {
  if (window.__bridgingMathObserverStarted) return;
  window.__bridgingMathObserverStarted = true;

  var timer;
  var schedule = function () {
    clearTimeout(timer);
    timer = setTimeout(function () {
      window.bridgingRenderMath();
      window.bridgingAttachMathObservers();
    }, 200);
  };

  window.bridgingWaitForKaTeX(function () {
    schedule();

    if (typeof MutationObserver !== 'function' || !document.body) return;

    window.__bridgingMathObserver = new MutationObserver(schedule);
    window.bridgingAttachMathObservers();

    new MutationObserver(schedule).observe(document.body, {
      childList: true,
      subtree: true,
    });
  });
};

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', window.bridgingEnsureMathObserver);
} else {
  window.bridgingEnsureMathObserver();
}

</script>
